package main

import "fmt"

// Buffer the channel so every sender can complete and exit even if
// main only reads the first result.
func first(queries []string) string {
	results := make(chan string, len(queries)) // buffered: sends never block
	for _, q := range queries {
		go func(q string) {
			results <- "result for " + q // always succeeds, goroutine exits
		}(q)
	}
	return <-results // others finish into the buffer, then are GC'd
}

func main() {
	fmt.Println(first([]string{"a", "b", "c"}))
}

