package solution

import (
	"context"
	"sync"
)

func FetchAll(ctx context.Context, ids []int, max int, fetch func(context.Context, int) int) []int {
	if max < 1 {
		max = 1
	}
	out := make([]int, len(ids))        // pre-sized: each index written once -> no race
	sem := make(chan struct{}, max)     // buffered channel as a counting semaphore
	var wg sync.WaitGroup

	for i, id := range ids {
		select {
		case <-ctx.Done(): // stop launching new work if cancelled
			wg.Wait()
			return out
		case sem <- struct{}{}: // acquire a slot (blocks once max are in flight)
		}
		wg.Add(1)
		go func(idx, id int) {
			defer wg.Done()
			defer func() { <-sem }() // release the slot on exit
			out[idx] = fetch(ctx, id) // distinct index -> safe without a lock
		}(i, id)
	}
	wg.Wait()
	return out
}

